INSERT INTO songs_test_lab (test_id, batch, source_project, creator, title, style_prompt, lyrics, genre, bpm, key_signature, note, status) VALUES (135, 'S_INST200', 'sunolanguage', 'sunolanguage', 'SI081', 'Chinese Traditional instrumental. Erhu plays a mournful, expressive melody with long sustained bows and subtle vibrato bending between notes. Guzheng provides cascading arpeggiated runs with crisp plucked attacks and delicate tremolo passages. Dizi delivers breathy, ornamented phrases with flutter-tonguing and pitch bends that float above the ensemble. The arrangement is contemplative and spacious, with each instrument taking turns leading the melodic narrative. 65 BPM in A Minor, 4/4 time signature.', NULL, 'Chinese Traditional', 65, 'A Minor', 'S_INST200 session3 Through-composed, 4/4', 'experimental');
INSERT INTO songs_test_lab (test_id, batch, source_project, creator, title, style_prompt, lyrics, genre, bpm, key_signature, note, status) VALUES (136, 'S_INST200', 'sunolanguage', 'sunolanguage', 'SI082', 'Japanese Koto instrumental. Koto plays meditative, pentatonic phrases with precise plucked attacks and resonant string bends that linger in the silence. Shakuhachi provides haunting, breathy melodic lines with controlled overblowing and subtle pitch fluctuations. Taiko enters with sparse, deep strikes that punctuate the stillness with thunderous resonance. The arrangement is austere and unhurried, embracing silence as a structural element between phrases. 55 BPM in Db Minor, 6/8 time signature.', NULL, 'Japanese Koto', 55, 'Db Minor', 'S_INST200 session3 Through-composed, 6/8', 'experimental');
INSERT INTO songs_test_lab (test_id, batch, source_project, creator, title, style_prompt, lyrics, genre, bpm, key_signature, note, status) VALUES (137, 'S_INST200', 'sunolanguage', 'sunolanguage', 'SI083', 'Korean Traditional instrumental. Gayageum plays ornate melodic passages with deep vibrato and sliding bends across silk strings. Haegeum provides sustained, expressive bowed lines with a nasal, penetrating tone and wide intervallic leaps. Daegeum delivers rich, breathy low-register phrases with characteristic buzzing membrane resonance and gentle trills. The arrangement is graceful and flowing, blending the three voices into an intimate chamber texture. 60 BPM in A Minor, 6/8 time signature.', NULL, 'Korean Traditional', 60, 'A Minor', 'S_INST200 session3 Through-composed, 6/8', 'experimental');
INSERT INTO songs_test_lab (test_id, batch, source_project, creator, title, style_prompt, lyrics, genre, bpm, key_signature, note, status) VALUES (138, 'S_INST200', 'sunolanguage', 'sunolanguage', 'SI084', 'Chinese Pipa instrumental. Pipa plays rapid tremolo picking with sharp, metallic attacks and dramatic downward sweeps across all four strings. Erhu provides sustained, sorrowful countermelodies with intense vibrato and sliding portamentos between phrases. Bamboo flute delivers airy, floating melodies with soft articulations and ornamental grace notes. The arrangement is dramatic and narrative, alternating between explosive pipa passages and delicate, lyrical interludes. 72 BPM in F# Minor, 3/4 time signature.', NULL, 'Chinese Pipa', 72, 'F# Minor', 'S_INST200 session3 Through-composed, 3/4', 'experimental');
INSERT INTO songs_test_lab (test_id, batch, source_project, creator, title, style_prompt, lyrics, genre, bpm, key_signature, note, status) VALUES (139, 'S_INST200', 'sunolanguage', 'sunolanguage', 'SI085', 'Shamisen Rock instrumental. Shamisen plays aggressive, percussive riffs with sharp bachi strikes and rapid-fire tremolo picking on thick silk strings. Taiko provides thunderous, driving rhythms with layered patterns between large odaiko booms and tight shime-daiko accents. Electric bass delivers distorted, low-end power riffs with palm-muted eighth notes and sliding chromatic runs. The drums feature a hard-hitting rock pattern with double kick accents and crashing cymbals. The arrangement is intense and relentless, fusing traditional Japanese ferocity with modern rock energy. 148 BPM in A Minor, 4/4 time signature.', NULL, 'Shamisen Rock', 148, 'A Minor', 'S_INST200 session3 Verse-Chorus, 4/4', 'experimental');
INSERT INTO songs_test_lab (test_id, batch, source_project, creator, title, style_prompt, lyrics, genre, bpm, key_signature, note, status) VALUES (140, 'S_INST200', 'sunolanguage', 'sunolanguage', 'SI086', 'Raga Evening instrumental. Sitar plays slow, meditative alap phrases with deep meend bends and shimmering sympathetic string resonance. Tabla provides gentle, intricate rhythmic cycles with soft fingertip bols and resonant bass strokes in an asymmetric pattern. Tanpura sustains a continuous, rich drone with layered overtones that create a hypnotic tonal foundation. The arrangement is devotional and expansive, allowing each phrase to breathe and dissolve into the drone. 48 BPM in Db Major, 7/8 time signature.', NULL, 'Raga Evening', 48, 'Db Major', 'S_INST200 session3 Through-composed, 7/8', 'experimental');
INSERT INTO songs_test_lab (test_id, batch, source_project, creator, title, style_prompt, lyrics, genre, bpm, key_signature, note, status) VALUES (141, 'S_INST200', 'sunolanguage', 'sunolanguage', 'SI087', 'Bhangra instrumental. Dhol drums play driving, syncopated rhythms with alternating heavy bass thumps and sharp, cracking treble strokes. Tumbi provides a bright, repetitive single-string melodic hook with a twangy, buzzing attack. Synthesizer delivers thick, layered brass stabs and pulsing pad chords that fill the midrange. The drums feature a relentless four-on-the-floor kick with clapped accents on the offbeats. The arrangement is euphoric and high-energy, built around the infectious dhol groove. 142 BPM in Bb Major, 4/4 time signature.', NULL, 'Bhangra', 142, 'Bb Major', 'S_INST200 session3 Verse-Chorus, 4/4', 'experimental');
INSERT INTO songs_test_lab (test_id, batch, source_project, creator, title, style_prompt, lyrics, genre, bpm, key_signature, note, status) VALUES (142, 'S_INST200', 'sunolanguage', 'sunolanguage', 'SI088', 'Qawwali featuring Urdu vocals. Harmonium plays sustained, droning chord progressions with a warm, reedy tone and subtle bellows dynamics. Tabla provides hypnotic, cyclical rhythmic patterns with crisp, articulate finger strokes building in intensity. Hand claps create a driving, communal pulse that accelerates with the devotional energy. The vocals deliver passionate, melismatic phrases with call-and-response patterns and ecstatic repetitions. The arrangement is devotional and intensifying, gradually building from a meditative opening to fervent climax. 90 BPM in Bb Minor, 4/4 time signature.', '[Verse 1]
Dil ke andar ek awaaz hai
Ishq ka ek raaz hai
Har lamha mein tera noor
Meri aankhon ka niyaaz hai

[Chorus]
Meri rooh teri talash mein
Har raat ka ye safar
Tera naam mere hothon pe
Tera ishq hai mera ghar

[Verse 2]
Chand sitaron mein chupa hai
Woh chehra jo yaad aata hai
Dard mein bhi sukoon milta hai
Jab dil tera naam gaata hai

[Chorus]
Meri rooh teri talash mein
Har raat ka ye safar
Tera naam mere hothon pe
Tera ishq hai mera ghar

[Bridge]
Sufi dil ke rang mein
Har dard ek tohfa hai
Jalta hai ye diya pyaar ka
Ishq ka ye silsila hai

[Final Chorus]
Meri rooh teri talash mein
Har raat ka ye safar
Tera naam mere hothon pe
Tera ishq hai mera ghar', 'Qawwali', 90, 'Bb Minor', 'S_INST200 session3 Through-composed, 4/4, vocal', 'experimental');
INSERT INTO songs_test_lab (test_id, batch, source_project, creator, title, style_prompt, lyrics, genre, bpm, key_signature, note, status) VALUES (143, 'S_INST200', 'sunolanguage', 'sunolanguage', 'SI089', 'Arabian Maqam instrumental. Oud plays ornate, microtonal melodic phrases with rapid tremolo picking and descending scalar runs across doubled courses. Ney provides a haunting, breathy tone with overblown harmonics and subtle quarter-tone inflections. Darbuka delivers crisp, intricate hand-drum patterns with sharp tek and dum strokes in complex subdivisions. The arrangement is meditative and improvisatory, weaving between composed melodic sections and spontaneous ornamental passages. 82 BPM in D Phrygian, 4/4 time signature.', NULL, 'Arabian Maqam', 82, 'D Phrygian', 'S_INST200 session3 Through-composed, 4/4', 'experimental');
INSERT INTO songs_test_lab (test_id, batch, source_project, creator, title, style_prompt, lyrics, genre, bpm, key_signature, note, status) VALUES (144, 'S_INST200', 'sunolanguage', 'sunolanguage', 'SI090', 'Persian Classical instrumental. Tar plays expressive, ornamented melodic lines with rapid tremolo strumming and delicate grace notes on a resonant skin-topped body. Santur provides shimmering, cascading runs with light mallet strikes that create a crystalline, bell-like texture. Tombak delivers precise, virtuosic finger patterns with alternating bass tones and sharp rim accents in a flowing compound meter. The arrangement is introspective and refined, following a traditional radif structure with improvised embellishments. 75 BPM in Eb Minor, 6/8 time signature.', NULL, 'Persian Classical', 75, 'Eb Minor', 'S_INST200 session3 Through-composed, 6/8', 'experimental');
INSERT INTO songs_test_lab (test_id, batch, source_project, creator, title, style_prompt, lyrics, genre, bpm, key_signature, note, status) VALUES (145, 'S_INST200', 'sunolanguage', 'sunolanguage', 'SI091', 'Afrobeats instrumental. Clean electric guitar plays bright, rhythmic chordal patterns with muted upstrokes and percussive ghost strums. Log drum provides a deep, resonant melodic bass pattern with syncopated rhythms that anchor the groove. Shakers deliver a constant, flowing sixteenth-note pulse with subtle dynamic swells. The drums feature a crisp, bouncing pattern with tight hi-hats and a snappy snare on the backbeat. The arrangement is infectious and laid-back, built around interlocking rhythmic layers that create a hypnotic dance groove. 108 BPM in Bb Minor, 4/4 time signature.', NULL, 'Afrobeats', 108, 'Bb Minor', 'S_INST200 session3 Verse-Chorus, 4/4', 'experimental');
INSERT INTO songs_test_lab (test_id, batch, source_project, creator, title, style_prompt, lyrics, genre, bpm, key_signature, note, status) VALUES (146, 'S_INST200', 'sunolanguage', 'sunolanguage', 'SI092', 'Highlife instrumental. Bright arpeggiated guitar plays interlocking melodic patterns with clean, ringing tones and nimble fingerpicking across the upper register. Brass section provides warm, jubilant horn lines with staccato accents and sustained harmonic pads. Percussion delivers layered polyrhythmic patterns with claves, congas, and a steady cowbell pulse. The drums feature a relaxed, swinging groove with a shuffled hi-hat and a deep, round kick. The arrangement is joyful and celebratory, with call-and-response phrases between guitar and horns. 112 BPM in A Major, 4/4 time signature.', NULL, 'Highlife', 112, 'A Major', 'S_INST200 session3 Verse-Chorus, 4/4', 'experimental');
INSERT INTO songs_test_lab (test_id, batch, source_project, creator, title, style_prompt, lyrics, genre, bpm, key_signature, note, status) VALUES (147, 'S_INST200', 'sunolanguage', 'sunolanguage', 'SI093', 'Amapiano instrumental. Log drum plays a bouncy, syncopated bass melody with deep, woody tones and rhythmic ghost notes. Piano chords provide warm, jazzy voicings with soft, sustained pads and occasional staccato stabs. Shakers deliver a smooth, flowing percussive texture with light, continuous eighth-note patterns. The drums feature a characteristic low-tempo bounce with a wide, boomy kick and sparse, crisp hi-hat taps. The arrangement is minimalist and groove-driven, letting the log drum melody and piano interplay carry the track. 113 BPM in Eb Major, 4/4 time signature.', NULL, 'Amapiano', 113, 'Eb Major', 'S_INST200 session3 Loop-based, 4/4', 'experimental');
INSERT INTO songs_test_lab (test_id, batch, source_project, creator, title, style_prompt, lyrics, genre, bpm, key_signature, note, status) VALUES (148, 'S_INST200', 'sunolanguage', 'sunolanguage', 'SI094', 'Gqom instrumental. Deep bass synth delivers a pounding, distorted sub-bass pattern with aggressive pitch bends and abrupt cutoffs. Minimal percussion provides raw, industrial-sounding hits with sparse claps and heavily processed snare rolls. Chanted patterns create hypnotic, looping vocal samples with rhythmic repetition and pitch-shifted layers. The drums feature a relentless, driving kick pattern with syncopated rimshots and filtered noise sweeps. The arrangement is dark and minimalist, building tension through repetition and stripped-back intensity. 152 BPM in Ab Minor, 4/4 time signature.', NULL, 'Gqom', 152, 'Ab Minor', 'S_INST200 session3 Loop-based, 4/4', 'experimental');
INSERT INTO songs_test_lab (test_id, batch, source_project, creator, title, style_prompt, lyrics, genre, bpm, key_signature, note, status) VALUES (149, 'S_INST200', 'sunolanguage', 'sunolanguage', 'SI095', 'Soukous instrumental. Bright arpeggiated guitar plays rapid, fluid melodic lines with clean, sparkling tones and intricate fingerpicked patterns that cascade across the fretboard. Bass guitar provides a deep, melodic groove with walking bass lines and rhythmic fills that lock with the percussion. Sebene rhythm guitar delivers tight, repetitive riff patterns with muted strumming and syncopated accents. The drums feature a fast, danceable pattern with rolling hi-hats and a punchy snare crack. The arrangement is exuberant and kinetic, building from a structured verse into an extended sebene jam section. 135 BPM in A Major, 4/4 time signature.', NULL, 'Soukous', 135, 'A Major', 'S_INST200 session3 Verse-Sebene, 4/4', 'experimental');
INSERT INTO songs_test_lab (test_id, batch, source_project, creator, title, style_prompt, lyrics, genre, bpm, key_signature, note, status) VALUES (150, 'S_INST200', 'sunolanguage', 'sunolanguage', 'SI096', 'Mbaqanga instrumental. Accordion plays bright, pumping chord patterns with bellows-driven dynamics and cheerful melodic fills. Pennywhistle provides piercing, agile melodic lines with rapid ornamental runs and a sharp, cutting tone. Electric guitar delivers clean, rhythmic strumming with muted scratch patterns and occasional wah-filtered fills. The drums feature a bouncing, shuffled groove with a deep bass drum and crisp snare backbeat. The arrangement is lively and communal, with a danceable township feel and trading melodic phrases between accordion and pennywhistle. 118 BPM in Bb Major, 4/4 time signature.', NULL, 'Mbaqanga', 118, 'Bb Major', 'S_INST200 session3 Strophic, 4/4', 'experimental');
INSERT INTO songs_test_lab (test_id, batch, source_project, creator, title, style_prompt, lyrics, genre, bpm, key_signature, note, status) VALUES (151, 'S_INST200', 'sunolanguage', 'sunolanguage', 'SI097', 'Ethiopian Jazz instrumental. Masinko plays soulful, one-stringed bowed melodies with intense vibrato and microtonal inflections rooted in pentatonic scales. Krar provides shimmering, plucked accompaniment with arpeggiated patterns and resonant open-string drones on its lyre-shaped frame. Kebero delivers deep, hand-struck rhythmic patterns with layered polyrhythmic accents in a swaying compound meter. The arrangement is atmospheric and contemplative, blending ancient Ethiopian modes with jazz-inflected harmonic explorations. 95 BPM in Eb Minor, 6/8 time signature.', NULL, 'Ethiopian Jazz', 95, 'Eb Minor', 'S_INST200 session3 Through-composed, 6/8', 'experimental');
INSERT INTO songs_test_lab (test_id, batch, source_project, creator, title, style_prompt, lyrics, genre, bpm, key_signature, note, status) VALUES (152, 'S_INST200', 'sunolanguage', 'sunolanguage', 'SI098', 'West African Drum Ensemble instrumental. Djembe plays dynamic, polyrhythmic patterns with alternating bass tones, open slaps, and sharp edge strikes. Balafon provides bright, wooden melodic phrases with rapid mallet runs and buzzing gourd resonators underneath. Shekere delivers a steady, shimmering rhythmic pulse with flowing bead patterns and sharp accented shakes. The drums feature interlocking hand percussion with talking drum fills and dunun bass patterns. The arrangement is communal and celebratory, building layers of rhythmic complexity in a call-and-response structure. 110 BPM in Ab Major, 12/8 time signature.', NULL, 'West African Drum Ensemble', 110, 'Ab Major', 'S_INST200 session3 Call-and-Response, 12/8', 'experimental');
INSERT INTO songs_test_lab (test_id, batch, source_project, creator, title, style_prompt, lyrics, genre, bpm, key_signature, note, status) VALUES (153, 'S_INST200', 'sunolanguage', 'sunolanguage', 'SI099', 'Kalimba Ambient instrumental. Kalimba plays gentle, repeating melodic patterns with soft, bell-like tines and natural buzzing overtones that shimmer and decay. Atmospheric pad provides a warm, evolving drone with slow filter sweeps and layered harmonic textures. Field recording adds subtle natural ambience with distant birdsong and soft wind that blends into the sonic landscape. The arrangement is tranquil and meditative, floating in an open, spacious mix with generous reverb and minimal processing. 55 BPM in F# Major, 3/4 time signature.', NULL, 'Kalimba Ambient', 55, 'F# Major', 'S_INST200 session3 Free-form, 3/4', 'experimental');
INSERT INTO songs_test_lab (test_id, batch, source_project, creator, title, style_prompt, lyrics, genre, bpm, key_signature, note, status) VALUES (154, 'S_INST200', 'sunolanguage', 'sunolanguage', 'SI100', 'Capoeira instrumental. Berimbau plays a hypnotic, single-string rhythmic pattern with distinctive buzzing attacks and pitch bends created by pressing a stone against the wire. Pandeiro provides a bright, syncopated tambourine groove with crisp thumb rolls and sharp frame slaps. Atabaque delivers deep, resonant hand-drum patterns with booming bass strokes and rapid fingertip fills. The arrangement is ritualistic and grounding, built around the circular berimbau ostinato with layered percussion intensifying through repetition. 120 BPM in Bb Minor, 4/4 time signature.', NULL, 'Capoeira', 120, 'Bb Minor', 'S_INST200 session3 Call-and-Response, 4/4', 'experimental');
INSERT INTO songs_test_lab (test_id, batch, source_project, creator, title, style_prompt, lyrics, genre, bpm, key_signature, note, status) VALUES (155, 'S_INST200', 'sunolanguage', 'sunolanguage', 'SI101', 'Salsa instrumental. Piano montuno plays a driving, syncopated comping pattern with bright, percussive chord stabs and rapid octave runs. Trumpet delivers bold, brassy melodic lines with sharp attacks and sustained high notes that cut through the ensemble. Timbales provide crisp, cascading shell patterns with explosive fills and sharp rimshot accents. The drums feature a tight clave-based pattern with a punchy kick and agogo bell marking the pulse. The arrangement is fiery and rhythmically complex, with montuno patterns driving the dance energy. 98 BPM in F Minor, 4/4 time signature.', NULL, 'Salsa', 98, 'F Minor', 'S_INST200 session3 Verse-Montuno, 4/4', 'experimental');
INSERT INTO songs_test_lab (test_id, batch, source_project, creator, title, style_prompt, lyrics, genre, bpm, key_signature, note, status) VALUES (156, 'S_INST200', 'sunolanguage', 'sunolanguage', 'SI102', 'Bachata instrumental. Nylon-string guitar plays romantic, arpeggiated patterns with warm fingerpicked tones and sliding grace notes between chord changes. Bongos provide a steady, syncopated martillo rhythm with soft fingertip rolls and sharp open-tone slaps on the offbeats. Guiro delivers a scratchy, rhythmic pulse with alternating long and short scraping strokes that drive the tempo forward. The arrangement is intimate and swaying, with the guitar melody carrying a melancholic, romantic mood over the gentle percussive groove. 130 BPM in A Minor, 4/4 time signature.', NULL, 'Bachata', 130, 'A Minor', 'S_INST200 session3 Verse-Chorus, 4/4', 'experimental');
INSERT INTO songs_test_lab (test_id, batch, source_project, creator, title, style_prompt, lyrics, genre, bpm, key_signature, note, status) VALUES (157, 'S_INST200', 'sunolanguage', 'sunolanguage', 'SI103', 'Klezmer instrumental. Clarinet plays exuberant, wailing melodies with rapid ornamental runs, dramatic glissandos, and laughing vibrato in the upper register. Accordion provides rich, chordal accompaniment with bellows-driven swells and a warm, buzzing drone bass. Violin delivers passionate, soaring countermelodies with intense vibrato and double-stopped harmonies. The drums feature a driving freylekhs rhythm with a brisk snare pattern and a stomping bass drum on the downbeat. The arrangement is festive and emotionally charged, alternating between jubilant dance sections and mournful, rubato passages. 130 BPM in Db Minor, 4/4 time signature.', NULL, 'Klezmer', 130, 'Db Minor', 'S_INST200 session3 AABB, 4/4', 'experimental');
INSERT INTO songs_test_lab (test_id, batch, source_project, creator, title, style_prompt, lyrics, genre, bpm, key_signature, note, status) VALUES (158, 'S_INST200', 'sunolanguage', 'sunolanguage', 'SI104', 'Russian Folk instrumental. Balalaika plays rapid, strummed tremolo patterns with a bright, metallic tone and rhythmic chordal bursts on its triangular body. Accordion provides driving, bellows-pumped bass lines with staccato chord stabs and melodic fills in the upper register. Domra delivers quick, mandolin-like melodic runs with precise plucked articulations and lively ornamental trills. The drums feature a brisk march-like pattern with a sharp snare crack and a steady bass drum pulse. The arrangement is spirited and propulsive, building momentum through accelerating dynamics and layered instrumental entries. 140 BPM in A Minor, 2/4 time signature.', NULL, 'Russian Folk', 140, 'A Minor', 'S_INST200 session3 Strophic, 2/4', 'experimental');
INSERT INTO songs_test_lab (test_id, batch, source_project, creator, title, style_prompt, lyrics, genre, bpm, key_signature, note, status) VALUES (159, 'S_INST200', 'sunolanguage', 'sunolanguage', 'SI105', 'Andean Folk instrumental. Charango plays bright, rapid strumming patterns with a high-pitched, shimmering tone and melodic runs across doubled string courses. Pan flute provides haunting, breathy melodies with soft, airy attacks and gentle vibrato that echoes across mountain valleys. Bombo drum delivers deep, resonant strikes with a booming low end and sharp rim accents that anchor the rhythm. The arrangement is pastoral and evocative, with layered textures that build from sparse solo passages to full ensemble crescendos. 100 BPM in Bb Minor, 4/4 time signature.', NULL, 'Andean Folk', 100, 'Bb Minor', 'S_INST200 session3 Strophic, 4/4', 'experimental');
INSERT INTO songs_test_lab (test_id, batch, source_project, creator, title, style_prompt, lyrics, genre, bpm, key_signature, note, status) VALUES (160, 'S_INST200', 'sunolanguage', 'sunolanguage', 'SI106', 'Scottish Highland instrumental. Bagpipe plays a stirring, sustained melody with continuous drone pipes and ornamental grace notes in a pentatonic major scale. Snare drum provides a tight, military-style pattern with crisp buzz rolls and sharp flam accents. Fiddle delivers lively, bowing double-stopped harmonies with quick ornamental turns and driving rhythmic bowing. The arrangement is bold and ceremonial, structured as a traditional march with a steady, processional build and layered drone harmonies. 110 BPM in A Major, 6/8 time signature.', NULL, 'Scottish Highland', 110, 'A Major', 'S_INST200 session3 March, 6/8', 'experimental');
INSERT INTO songs_test_lab (test_id, batch, source_project, creator, title, style_prompt, lyrics, genre, bpm, key_signature, note, status) VALUES (161, 'S_INST200', 'sunolanguage', 'sunolanguage', 'SI107', 'Harpsichord Concerto instrumental. Harpsichord plays elaborate, ornamental passages with crisp, plucked articulation and rapid scalar runs in a brilliant, metallic tone. String ensemble provides rich, sustained harmonic support with legato bowing and warm contrapuntal lines. Oboe delivers lyrical, singing melodies with a warm, reedy tone and graceful phrasing over the ensemble texture. The arrangement is elegant and structured, following a Baroque ritornello form with alternating solo and tutti sections. 105 BPM in Db Major, 3/4 time signature.', NULL, 'Harpsichord Concerto', 105, 'Db Major', 'S_INST200 session3 Ritornello, 3/4', 'experimental');
INSERT INTO songs_test_lab (test_id, batch, source_project, creator, title, style_prompt, lyrics, genre, bpm, key_signature, note, status) VALUES (162, 'S_INST200', 'sunolanguage', 'sunolanguage', 'SI108', 'Celesta Lullaby instrumental. Celesta plays a gentle, twinkling melody with crystalline, bell-like tones and delicate, music-box articulation. Harp provides soft, arpeggiated accompaniment with warm, resonant glissandos and sustained pedal tones. Soft strings deliver hushed, legato pads with a warm, enveloping texture and subtle dynamic swells beneath the melody. The arrangement is tender and dreamlike, with a sparse, transparent mix and gentle dynamic breathing that rocks like a cradle. 48 BPM in F# Major, 6/8 time signature.', NULL, 'Celesta Lullaby', 48, 'F# Major', 'S_INST200 session3 Strophic, 6/8', 'experimental');
INSERT INTO songs_test_lab (test_id, batch, source_project, creator, title, style_prompt, lyrics, genre, bpm, key_signature, note, status) VALUES (163, 'S_INST200', 'sunolanguage', 'sunolanguage', 'SI109', 'Theremin Ambient instrumental. Theremin plays eerie, wavering melodic lines with smooth portamento glides and a haunting, voice-like vibrato. Modular synthesizer provides evolving, generative textures with slowly morphing filter sweeps and granular noise bursts. Tape loops deliver warped, degraded sonic fragments with wow and flutter artifacts and reversed ambient layers. The arrangement is otherworldly and disorienting, suspending time with asymmetric phrasing and vast, cavernous reverb spaces. 40 BPM in Eb Minor, 5/4 time signature.', NULL, 'Theremin Ambient', 40, 'Eb Minor', 'S_INST200 session3 Free-form, 5/4', 'experimental');
INSERT INTO songs_test_lab (test_id, batch, source_project, creator, title, style_prompt, lyrics, genre, bpm, key_signature, note, status) VALUES (164, 'S_INST200', 'sunolanguage', 'sunolanguage', 'SI110', 'Chiptune instrumental. 8-bit square wave plays rapid, energetic melodic lines with bright, buzzy tones and fast arpeggiated patterns that cascade through octaves. Triangle bass provides a smooth, warm low-end pulse with simple, driving root-note patterns. Noise percussion delivers crisp, lo-fi drum patterns with sharp, static-burst snares and rapid-fire hi-hat ticks. The arrangement is hyperactive and playful, with dense, layered countermelodies and abrupt key changes that evoke retro arcade energy. 155 BPM in Bb Major, 4/4 time signature.', NULL, 'Chiptune', 155, 'Bb Major', 'S_INST200 session3 Verse-Chorus, 4/4', 'experimental');
INSERT INTO songs_test_lab (test_id, batch, source_project, creator, title, style_prompt, lyrics, genre, bpm, key_signature, note, status) VALUES (165, 'S_INST200', 'sunolanguage', 'sunolanguage', 'SI111', 'Bassoon Quartet instrumental. Bassoon plays rich, warm melodic lines with a deep, woody tone and subtle vibrato in the lower register. Oboe provides a bright, piercing countermelody with delicate phrasing and expressive dynamic shading. Clarinet delivers smooth, fluid passages with a silky, rounded tone and agile ornamental runs. The arrangement is refined and conversational, with contrapuntal voices weaving through elegant three-part harmonies in a classical rondo form. 100 BPM in F Major, 3/4 time signature.', NULL, 'Bassoon Quartet', 100, 'F Major', 'S_INST200 session3 Rondo (ABACA), 3/4', 'experimental');
INSERT INTO songs_test_lab (test_id, batch, source_project, creator, title, style_prompt, lyrics, genre, bpm, key_signature, note, status) VALUES (166, 'S_INST200', 'sunolanguage', 'sunolanguage', 'SI112', 'Recorder Consort instrumental. Soprano recorder plays a clear, bright melodic line with precise articulation and gentle ornamental trills in the upper register. Alto recorder provides warm, singing countermelodies with a mellow, rounded tone and flowing legato phrasing. Bass recorder delivers a deep, resonant foundation with breathy, sustained bass notes and slow-moving harmonic support. The arrangement is intimate and polished, featuring Renaissance-style imitative polyphony with staggered melodic entries. 88 BPM in Db Major, 3/4 time signature.', NULL, 'Recorder Consort', 88, 'Db Major', 'S_INST200 session3 Binary (AB), 3/4', 'experimental');
INSERT INTO songs_test_lab (test_id, batch, source_project, creator, title, style_prompt, lyrics, genre, bpm, key_signature, note, status) VALUES (167, 'S_INST200', 'sunolanguage', 'sunolanguage', 'SI113', 'Marimba Ensemble instrumental. Marimba plays rapid, interlocking melodic patterns with soft mallets producing warm, woody tones and resonant sustain. Vibraphone provides shimmering, sustained chords with slow motor vibrato and bell-like harmonic overtones. Glockenspiel delivers bright, sparkling accents with a crystalline attack that punctuates the rhythmic texture. The arrangement is hypnotic and rhythmically complex, with phasing patterns and hocketed melodies in an asymmetric five-beat groove. 120 BPM in Bb Major, 5/4 time signature.', NULL, 'Marimba Ensemble', 120, 'Bb Major', 'S_INST200 session3 Theme-Variations, 5/4', 'experimental');
INSERT INTO songs_test_lab (test_id, batch, source_project, creator, title, style_prompt, lyrics, genre, bpm, key_signature, note, status) VALUES (168, 'S_INST200', 'sunolanguage', 'sunolanguage', 'SI114', 'Steel Drum Calypso instrumental. Steel drum plays bright, melodic phrases with a resonant, metallic ring and syncopated rhythmic accents that bounce between chord tones. Bass guitar provides a deep, rolling bass line with smooth legato slides and a warm, round tone. Cowbell delivers a steady, driving pulse with sharp metallic clicks on the offbeats. The drums feature a relaxed, calypso-style groove with brushed snare and a light, bouncing kick pattern. The arrangement is sunny and festive, with the steel drum melody dancing over a laid-back Caribbean groove. 118 BPM in F Major, 4/4 time signature.', NULL, 'Steel Drum Calypso', 118, 'F Major', 'S_INST200 session3 Verse-Chorus, 4/4', 'experimental');
INSERT INTO songs_test_lab (test_id, batch, source_project, creator, title, style_prompt, lyrics, genre, bpm, key_signature, note, status) VALUES (169, 'S_INST200', 'sunolanguage', 'sunolanguage', 'SI115', 'Hang Drum Meditation instrumental. Hang drum plays resonant, bell-like melodic patterns with soft finger strikes and rich, sustaining overtones that bloom and decay naturally. Atmospheric pad provides a warm, evolving drone with slow harmonic shifts and ethereal, choir-like textures. Field recording adds subtle natural ambience with gentle rain and distant water flowing into the sonic space. The arrangement is serene and spacious, with generous silence between phrases and deep, immersive reverb. 60 BPM in Db Minor, 4/4 time signature.', NULL, 'Hang Drum Meditation', 60, 'Db Minor', 'S_INST200 session3 Free-form, 4/4', 'experimental');
INSERT INTO songs_test_lab (test_id, batch, source_project, creator, title, style_prompt, lyrics, genre, bpm, key_signature, note, status) VALUES (170, 'S_INST200', 'sunolanguage', 'sunolanguage', 'SI116', 'Taiko Ensemble instrumental. Taiko drums play thunderous, full-bodied strikes with massive low-end resonance and dynamic patterns that alternate between single booms and rapid rolls. Shime-daiko provides tight, high-pitched accents with crisp, cutting attacks and intricate rhythmic subdivisions. Kane delivers sharp, metallic bell strikes that punctuate the rhythmic phrases with bright, ringing accents. The arrangement is powerful and ceremonial, building from sparse solo passages to overwhelming full-ensemble crescendos with choreographed precision. 92 BPM in Db Major, 4/4 time signature.', NULL, 'Taiko Ensemble', 92, 'Db Major', 'S_INST200 session3 Through-composed, 4/4', 'experimental');
INSERT INTO songs_test_lab (test_id, batch, source_project, creator, title, style_prompt, lyrics, genre, bpm, key_signature, note, status) VALUES (171, 'S_INST200', 'sunolanguage', 'sunolanguage', 'SI117', 'Mongolian Throat Singing featuring Mongolian vocals. Morin khuur plays haunting, sustained bowed melodies with a warm, horse-hair string tone and wide vibrato on a carved horse-head fiddle. Throat singing drone provides deep, guttural overtone harmonics with two simultaneous pitches and a rich, buzzing resonance. Frame drum delivers sparse, steady strikes with a deep, booming tone and subtle rattling overtones. The vocals feature khoomei-style overtone singing with a resonant fundamental and whistling harmonic melodies. The arrangement is vast and primordial, evoking open steppes and windswept landscapes. 62 BPM in Eb Minor, 4/4 time signature.', '[Verse 1]
Хөх тэнгэрийн доор
Салхи морьтой давхина
Нарны гэрэл алтаар
Тал нутгийг гийгүүлнэ

[Chorus]
Монгол нутаг минь
Үүрд мөнхийн газар
Эцэг өвгөдийн дуу
Зүрхэнд минь мөнхөд байна

[Verse 2]
Уулсын цаана
Голын ус цэнгэлтэй урсана
Гэрийн утаа тэнгэрт
Шувуудын дуу сонсогдоно

[Chorus]
Монгол нутаг минь
Үүрд мөнхийн газар
Эцэг өвгөдийн дуу
Зүрхэнд минь мөнхөд байна', 'Mongolian Throat Singing', 62, 'Eb Minor', 'S_INST200 session3 Through-composed, 4/4, vocal', 'experimental');
INSERT INTO songs_test_lab (test_id, batch, source_project, creator, title, style_prompt, lyrics, genre, bpm, key_signature, note, status) VALUES (172, 'S_INST200', 'sunolanguage', 'sunolanguage', 'SI118', 'Dubstep instrumental. Wobble bass delivers a massive, modulated low-frequency oscillation with rapid filter cutoff automation and distorted overtones. Aggressive sub-bass provides a crushing, floor-shaking foundation with pitch-bent drops and growling resonance. Half-time drums feature a heavy, syncopated breakbeat pattern with snapping snares and scattered, glitchy hi-hat fills. The arrangement is brutal and dynamic, built around tension-and-release cycles with atmospheric buildups exploding into devastating bass drops. 140 BPM in Ab Minor, 4/4 time signature.', NULL, 'Dubstep', 140, 'Ab Minor', 'S_INST200 session3 Build-Drop, 4/4', 'experimental');
INSERT INTO songs_test_lab (test_id, batch, source_project, creator, title, style_prompt, lyrics, genre, bpm, key_signature, note, status) VALUES (173, 'S_INST200', 'sunolanguage', 'sunolanguage', 'SI119', 'Enka featuring Japanese vocals. Shamisen plays sparse, rhythmic accompaniment with sharp bachi plucking and melodic fills between vocal phrases. Koto provides delicate, arpeggiated harmonic support with gentle plucked patterns and subtle string bends. Shakuhachi delivers haunting, breathy interludes with controlled overblowing and expressive pitch bending. The vocals feature a rich, melismatic singing style with dramatic vibrato and emotional kobushi ornamentation. The arrangement is elegant and emotionally intense, with restrained instrumentation that showcases the vocal drama. 70 BPM in C# Minor, 4/4 time signature.', '[Verse 1]
夜の港に 波が寄せて
遠い灯りが 揺れている
あなたの声が 風に乗って
この胸の中 響いている

[Chorus]
忘れられない あの日の空
涙の雨が 降り続く
ただひとつだけ 願いがある
もう一度だけ 会いたくて

[Verse 2]
桜散る道 ひとり歩く
思い出だけが 寄り添って
月が照らした あの小道を
今もまだ夢に 見ている

[Chorus]
忘れられない あの日の空
涙の雨が 降り続く
ただひとつだけ 願いがある
もう一度だけ 会いたくて

[Bridge]
季節は巡り 時は流れ
変わらぬ想い 胸に抱いて

[Final Chorus]
忘れられない あの日の空
涙の雨が 降り続く
ただひとつだけ 願いがある
もう一度だけ 会いたくて', 'Enka', 70, 'C# Minor', 'S_INST200 session3 Strophic, 4/4, vocal', 'experimental');
INSERT INTO songs_test_lab (test_id, batch, source_project, creator, title, style_prompt, lyrics, genre, bpm, key_signature, note, status) VALUES (174, 'S_INST200', 'sunolanguage', 'sunolanguage', 'SI120', 'Fado featuring Portuguese vocals. Portuguese guitar plays intricate, tremolo melodic lines with a bright, metallic twelve-string tone and rapid ornamental runs. Nylon-string guitar provides warm, fingerpicked harmonic accompaniment with gentle arpeggiated chords and rhythmic strumming. Upright bass delivers a deep, resonant foundation with slow, legato walking lines and sustained root notes. The vocals feature a powerful, emotionally raw singing style with melismatic phrasing and aching vibrato. The arrangement is intimate and melancholic, with sparse instrumentation that lets the saudade of the voice fill the room. 65 BPM in F Minor, 3/4 time signature.', '[Verse 1]
Na noite escura do mar
As ondas cantam saudade
Um barco longe a navegar
Levando a minha metade

[Chorus]
O fado, o destino meu
Que dor tao grande me deste
O amor que me prometeu
Foi sombra que apareceste

[Verse 2]
Nas ruas velhas da cidade
A lua chora comigo
Guardei no peito a verdade
De um amor que foi castigo

[Chorus]
O fado, o destino meu
Que dor tao grande me deste
O amor que me prometeu
Foi sombra que apareceste

[Bridge]
A guitarra chora baixinho
A noite abraca o silencio
Sigo sozinho o caminho
Da saudade e do misterio

[Final Chorus]
O fado, o destino meu
Que dor tao grande me deste
O amor que me prometeu
Foi sombra que apareceste', 'Fado', 65, 'F Minor', 'S_INST200 session3 Strophic, 3/4, vocal', 'experimental');
